import fs from "node:fs/promises";
import { createReadStream } from "node:fs";
import path from "node:path";
import { Readable } from "node:stream";
import { config } from "../config";

/**
 * Attachment storage. Files live on disk under DATA_DIR/attachments, which is
 * a Docker volume in production. Keys are generated by Issueit, never taken
 * from user input, and are checked to stay inside the root.
 */
const root = path.resolve(config.dataDir, "attachments");

function resolveKey(key: string) {
  const full = path.resolve(root, key);
  if (!full.startsWith(root + path.sep)) throw new Error("Invalid storage key");
  return full;
}

export const storage = {
  async put(key: string, data: Uint8Array) {
    const full = resolveKey(key);
    await fs.mkdir(path.dirname(full), { recursive: true });
    await fs.writeFile(full, data, { flag: "wx" });
  },
  async stream(key: string): Promise<ReadableStream> {
    const full = resolveKey(key);
    await fs.access(full);
    return Readable.toWeb(createReadStream(full)) as ReadableStream;
  },
  async read(key: string): Promise<Buffer> {
    return fs.readFile(resolveKey(key));
  },
  async remove(key: string) {
    await fs.rm(resolveKey(key), { force: true });
  },
  async removePrefix(prefix: string) {
    await fs.rm(resolveKey(prefix), { recursive: true, force: true });
  },
};
